export function productPlan(id?: string | null) { return PRODUCT_PLANS.find(plan => plan.id === id) }
export function planText(plan: ProductPlan): string {
 return [`# ${plan.title} — Plan and Vision`, `Revision: ${PLAN_REVISION}`, plan.purpose, `## Implementation baseline\n${plan.baseline}`, ...plan.branches.map(b => `## ${b.title}\n${b.notes.map(n => `- ${n}`).join("\n")}`), `## Build sequence\n${plan.phases.map((p,i) => `${i+1}. ${p}`).join("\n")}`, `## Acceptance checks\n${plan.acceptance.map(c => `- ${c}`).join("\n")}`, journalMarkdown(plan.id), `## Source files\n${plan.sources.map(s => `- ${s}`).join("\n")}`, "## Developer handoff\nEdit src/lib/plan-vision.ts through a reviewed commit. All views and exports use this model. Include changed behavior, acceptance evidence, remaining gaps and release commit in the handoff. Phase order does not mean completed work. Owners and dates remain unassigned until agreed."].join("\n\n") + "\n"
}
const xml = (s: string) => s.replace(/[<>&"']/g, c => ({"<":"&lt;", ">":"&gt;", "&":"&amp;", '"':"&quot;", "'":"&apos;"})[c]!)
function wrap(s: string, limit: number) { const lines: string[] = []; let line = ""; for (const w of s.split(/\s+/)) { if (line && (line+" "+w).length > limit) { lines.push(line); line=w } else line+=(line?" ":"")+w } if(line)lines.push(line); return lines }
export function planImage(plan: ProductPlan): string {
 const text=(s:string,x:number,y:number,size:number,color:string,limit:number)=>`<text x="${x}" y="${y}" font-family="Arial, sans-serif" font-size="${size}" fill="${color}">${wrap(s,limit).map((line,i)=>`<tspan x="${x}" dy="${i?size*1.45:0}">${xml(line)}</tspan>`).join("")}</text>`
 return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1180" viewBox="0 0 1200 1180" role="img" aria-labelledby="title desc"><title id="title">${xml(plan.title)} Plan and Vision</title><desc id="desc">${xml(plan.purpose)} Planned work is not a completion claim.</desc><rect width="1200" height="1180" fill="#101c29"/>${text("MFIT / DEVELOPER NOTES / "+PLAN_REVISION,56,58,15,"#9bb2c8",100)}${text(plan.title+" · Plan and Vision",56,114,36,"#ffffff",60)}${text(plan.purpose,56,158,20,"#d4e2ef",91)}<path d="M600 205V230M318 230H882M318 230V250M882 230V250" stroke="#6bd6c3" fill="none" stroke-width="2"/>${plan.branches.map((b,i)=>{const x=56+(i%2)*560,y=250+Math.floor(i/2)*270;return `<rect x="${x}" y="${y}" width="528" height="242" rx="14" fill="#1a2c3e" stroke="#3d586e"/>${text(String(i+1).padStart(2,"0"),x+24,y+36,16,"#6bd6c3",10)}${text(b.title,x+24,y+70,22,"#ffffff",38)}${text(b.notes[0],x+24,y+128,17,"#d4e2ef",53)}`}).join("")}${text("BUILD SEQUENCE",56,822,17,"#6bd6c3",70)}${plan.phases.map((p,i)=>text(`${i+1}. ${p}`,56,862+i*48,17,"#e2ebf3",109)).join("")}${text("Vision and delivery plan · Validate each phase before marking it shipped.",56,1150,15,"#9bb2c8",120)}</svg>`
}
